    if(isRouter(k)) refreshRouterInputs(k);
    /* VideoSource width/height are part of the Source preset snapshot, not a
       global browser preference. Apply them to this Clip only; reset still
       uses the Clip parameter defaults because setParam never rewrites def. */
    if(record.source){
      if(Number.isFinite(+record.source.width)) EN.setParam(k.video.width,+record.source.width);
      if(Number.isFinite(+record.source.height)) EN.setParam(k.video.height,+record.source.height);
    }
    presetRecordParams(record).forEach(saved=>applyPresetParam(source,source.params,saved));
    applyPresetAnimations(source,source.params,record);
