  const stateLabel=state.error?'Control error':state.protectedView?'Enable Editing in PowerPoint':preparing?'Opening original PowerPoint…':pictureError?'Picture unavailable':powerpointTimeBusyVisible?'Connecting…':running?'Slide Show running':state.connected?'Presentation open':'Not connected';
  if(stateEl.textContent!==stateLabel)stateEl.textContent=stateLabel;
