let powerpointTimePending=null;
async function runPowerpointTimeControl(path,quiet){
  if(S.live)return null;
  if(powerpointTimeBusy){
    const pending=powerpointTimePending;
    /* Quiet discovery leaves the toolbar usable. Preserve the first explicit
       click and visibly wait for that read before sending its command once. */
    if(quiet||!pending||!pending.quiet||pending.operation!=='status'||pending.queued)return null;
    pending.queued=true;
    const owner=presentationNativeDeck,session=powerpointTimeState.sessionId;
    powerpointTimeBusyVisible=true;paintPowerpointTimePanel();
    await pending.done;
    if(S.live)return null;
    if(presentationNativeDeck!==owner||session&&powerpointTimeState.sessionId!==session){
      msg('The pinned PowerPoint changed while waiting. Select its control again.');return null;
    }
    return runPowerpointTimeControl(path,false);
  }
  const operation=path.split('?')[0];
  const preparation=nativePresentationCurrent(presentationNativeDeck)&&presentationNativeDeck.native.openPromise;
  if(quiet&&preparation)return null;
  if(!quiet&&operation==='status'&&nativePresentationCurrent(presentationNativeDeck))
    return prepareNativePresentationClip(presentationNativeDeck.clip,{refresh:true});
  if(!quiet&&operation==='connect'&&nativePresentationCurrent(presentationNativeDeck)&&
    presentationNativeDeck.clip.media&&presentationNativeDeck.clip.media.nativePresentation===presentationNativeDeck.native){
    const own=presentationNativeDeck;
    const state=await prepareNativePresentationClip(own.clip);
    if(!state||!state.connected||!nativePresentationCurrent(presentationNativeDeck)||presentationNativeDeck.native!==own.native)return null;
  }
  if(operation==='status'&&nativePresentationCurrent(presentationNativeDeck)&&
    !presentationNativeDeck.native.sessionId)return null;
  const priorNative=presentationNativeDeck,pinnedNative=nativePresentationCurrent(priorNative)&&priorNative.native.sessionId;
  const retarget=operation==='import'||operation==='connect'&&!path.includes('presenter=true')&&!pinnedNative;
  if(retarget){if(presentationPlayer&&presentationPlayer.mode==='live')retirePresentationPlayer();presentationNativeDeck=null;}
  let finish;const pending={operation,quiet:!!quiet,queued:false,done:new Promise(resolve=>{finish=resolve;})};
  powerpointTimePending=pending;
  powerpointTimeBusy=true;powerpointTimeBusyVisible=!quiet;if(!quiet)paintPowerpointTimePanel();
  const prior=powerpointTimeState;
  try{
    const state=await powerpointLiveRequest(path,{session:retarget?null:prior.sessionId});
    if(powerpointTimeState!==prior)return null;
    if(state.cancelled){if(retarget)presentationNativeDeck=priorNative;return state;}
    if(!retarget&&nativePresentationCurrent(priorNative)&&state.sessionId===priorNative.native.sessionId){
      priorNative.native.status=state;priorNative.native.state=state.protectedView?'protected':state.connected?'open':'disconnected';priorNative.native.error=null;
      if(typeof clearNativePresentationImportBlock==='function')clearNativePresentationImportBlock(priorNative.clip,priorNative.native);
    }
    setPowerpointTimeState(state,null);return state;
  }catch(error){
    if(powerpointTimeState!==prior)return null;
    if(retarget)presentationNativeDeck=priorNative;
    const message=error&&error.message||error;
    if(!retarget&&nativePresentationCurrent(priorNative)){
      priorNative.native.error=String(message);priorNative.native.state='error';refreshThumbCache();
    }
    if(prior.sessionId||quiet&&(prior.connected||prior.running||prior.slideCount)){
      powerpointTimeState=Object.assign({},powerpointTimeState,{error:String(message)});paintPowerpointTimePanel();
    }else setPowerpointTimeState(null,message);
    if(!quiet)msg(powerpointTimeState.error);return null;
  }finally{
    powerpointTimeBusy=false;powerpointTimeBusyVisible=false;powerpointTimeCheckedAt=Date.now();
    if(powerpointTimePending===pending)powerpointTimePending=null;
    finish();paintPowerpointTimePanel();
  }
}
