function commitEngineTextInput(input){
  if(!input || !input.matches || !input.matches('.etext[data-ep]')) return false;
  const p=EN.param(input.dataset.ep); if(!p) return false;
  const next=String(input.value == null ? '' : input.value);
  /* `change` is not a reliable commit boundary for this control: Enter does
     not blur a text input, and on Windows a right-click can open the Layer
     menu without moving focus. If that menu rebuilds the inspector, the
     uncommitted DOM value disappears. Compare with the Parameter first so
     Enter -> change -> blur, or a rebuild followed by blur, still creates one
     engine write and therefore one Undo entry. */
  if(String(p.value == null ? '' : p.value)===next) return false;
  EP(p,next);
  const layer=!S.live && S.pane==='pLayer' ? EN.layer(S.selLayer) : null;
  if(layer && p===layer.name){
    syncPropertyPanelTitle(true);
    render.layers(); render.grid();
  }
  const composition=!S.live && S.pane==='pComp' ? EN.comp() : null;
  if(composition && p===composition.name){
    syncPropertyPanelTitle(true);
    render.chrome();
  }
  return true;
}

function buildPanel(){
  const body=$('#pbody');
  /* Commit the focused engine string before replacing its DOM node. This is
     the path used when a Layer menu action or another surface rebuilds the
     inspector while right-click has deliberately kept keyboard focus here. */
  const active=document.activeElement;
  if(active && body.contains(active) && active.matches('.etext[data-ep]'))
    commitEngineTextInput(active);
  syncPropertyPanelTitle(); syncPropertyPanelMenuButton();
  /* A panel refresh replaces the exact Effect/Source instance controls. Close
     its popup first so no detached opener can keep an orphan menu alive. */
  if(dd.some(menu=>menu._opener && body.contains(menu._opener))) closeDD();
  /* PRESENT IS A HOST, NOT A PANE. Its controls are static markup bound once
     at load, so they live in #pbodyPresent beside #pbody rather than being
     re-rendered into it. Swap which of the two is visible; both are .pbody
     with flex:1, so exactly one must be hidden or they fight for the space.
     Note also that browserPreviewPanel() is prepended to EVERY pane string —
     a string-rendered Present would carry a browser-preview card above the
     PowerPoint controls whenever a preview is set. Another reason for a host. */
  const present = $('#pbodyPresent');
  const showPresent = S.pane==='pPresent';
  if(present){ present.hidden = !showPresent; }
  body.hidden = showPresent;
  if(showPresent){ paintPowerpointTimePanel(); bindClipTimeControls(); return; }
  const set = S.live ? LIVE_PANELS : ENGINE_PANELS;
  const fn = set[S.pane] || set.pLayer;
  body.innerHTML = browserPreviewPanel()+(fn() || '');
  fillEnums(body);
  $$('#pbody .sect > h3').forEach(h=>h.addEventListener('click',e=>{
    if(e.target.classList.contains('pbtn')) return;
    h.parentElement.classList.toggle('folded'); }));
  bindParams($('#pbody'));
  /* Preview rows are local engine Parameters even when the lower panel is a
     connected REST view. The binders use disjoint class names. */
  bindEngineRows($('#pbody'));
  bindLiveCaptureControls($('#pbody'));
  bindClipTrackRows($('#pbody'));
  bindLightingClipControls($('#pbody'));
  bindPresentationControls($('#pbody'));
  /* the Clip Time pane re-creates .ct-cliptime on every render, so its click
     flip and the gear have to be re-bound; both guard with a data flag so the
     pinned right-column copies are bound once and never twice. */
  bindClipTimeControls();
  paintClipTime();
  bindSectionPresetButtons($('#pbody'));
  if(!S.live) bindInstancePresetButtons($('#pbody'));
  bindBrowserPreviewApply(body);
  const previewClose=body.querySelector('[data-browser-preview-close]');
  if(previewClose) previewClose.addEventListener('click',event=>{
    event.preventDefault(); event.stopPropagation();
    clearBrowserPreview();
    if(typeof updateBrowserWorkflowDetail==='function') updateBrowserWorkflowDetail();
    const name=clipName(S.selLayer,S.selCol)||'empty';
    $('#fPreview').textContent='Preview / Clip: '+name;
    buildPanel();
    const title=$('#pTitle'); if(title) title.focus();
  });
  const chaserOpen=body.querySelector('[data-open-chaser-from-preview]');
  if(chaserOpen) chaserOpen.addEventListener('click',event=>{
    event.preventDefault(); event.stopPropagation();
    const preview=S.browserPreview, C=window.OpenLiveChaser;
    if(preview&&preview.name==='Checkered'&&C){
      const values=Object.fromEntries((preview.params||[]).map(param=>[param.name,EV(param)]));
      /* These are Checkered's mined native defaults. Falling back to the old
         8 × 8 Chaser starter changed the source before it was even cloned. */
      const numX=clamp(Math.round(Number(values['Num X'])||32),1,128);
      const numY=clamp(Math.round(Number(values['Num Y'])||18),1,128);
      /* "Clone" starts an independent chase instead of mutating whichever
         project the operator happened to edit last. Prefer the live Input Map;
         without one, the Checkered grid becomes the logical starter map. */
      const liveMap=C.liveMap;
      const project=C.createProject(liveMap&&liveMap.screens&&liveMap.screens.length
        ? liveMap : C.checkeredMap(numX,numY));
      project.name='Checkered Chase';
      project.pixelMap.numX=numX;
      project.pixelMap.numY=numY;
      if(Number.isFinite(Number(values['Color 1']))) project.pixelMap.color1=Number(values['Color 1'])>>>0;
      if(Number.isFinite(Number(values['Color 2']))) project.pixelMap.color2=Number(values['Color 2'])>>>0;
      /* Resolume's Checkered colors each carry alpha. Keep transparent and
         translucent clones off the Chaser's otherwise-opaque black backing. */
      project.pixelMap.transparent=[project.pixelMap.color1,project.pixelMap.color2]
        .some(color=>((Number(color)>>>24)&255)<255);
      project.updatedAt=Date.now(); C.setProject(project);
      if(window.OpenLiveHub){
        const saved=C.shareableProject ? C.shareableProject(project) : project;
        if(OpenLiveHub.patch) OpenLiveHub.patch('chaser',
          {schema:C.schema||1,project:saved,updatedAt:project.updatedAt},
          {reason:'Clone Checkered into SHOWAVE Chaser'});
        else if(OpenLiveHub.set) OpenLiveHub.set('chaser.project',saved,
          {reason:'Clone Checkered into SHOWAVE Chaser'});
      }
    }
    openPanel('chaser.html');
  });
  /* offline sliders keep the old cosmetic behaviour */
  if(!S.live){
    $$('#pbody input[type=range]:not(.pbind)').forEach(r=>r.addEventListener('input',()=>{
      const v=r.parentElement.querySelector('.val');
      if(v){ const suf=v.textContent.replace(/[-\d.]/g,'').trim(); v.textContent=r.value+(suf?' '+suf:''); }
    }));
    $$('#pbody .stp:not([data-pid])').forEach(s=>s.addEventListener('click',()=>{
      const r=s.parentElement.querySelector('input[type=range]'); if(!r) return;
      r.value=+r.value+(s.textContent==='+'?1:-1); r.dispatchEvent(new Event('input')); }));
    $$('#pbody .dial .k:not(.pdial)').forEach(k=>k.addEventListener('mousedown',e=>{
      const y=e.clientY, r0=parseFloat(k.style.getPropertyValue('--rot'))||0;
      const mv=ev=>k.style.setProperty('--rot',clamp(r0+(y-ev.clientY)*2,-135,135)+'deg');
      const up=()=>{removeEventListener('mousemove',mv);removeEventListener('mouseup',up);};
      addEventListener('mousemove',mv); addEventListener('mouseup',up); }));
  }
  restoreEffectFocus($('#pbody'));
}

function selectedPresentationClip(){
  if(S.live||(S.pane!=='pClip'&&S.pane!=='pPresent')) return null;
  const clip=EN.clip(S.selLayer,S.selCol);
  if(!clip||!clip.media||!clip.media.presentation) return null;
  /* The Clip pane can outlive a structural move for one render turn. Never let
     a stale Layer/Column pair turn a presentation click into a different Clip
     command. A clicker is scoped to the primary selected Clip, not the Column. */
  if(S.selClip&&S.selClip!==cid(S.selLayer,S.selCol)) return null;
  return clip;
}
function setPresentationSlide(media,index,options={}){
  if(options.signal?.aborted||options.isCurrent&&options.isCurrent()!==true)return false;
  const deck=media&&media.presentation;
  if(!deck||!Array.isArray(deck.pages)||!deck.pages.length) return false;
  const next=clamp(Math.round(Number(index)||0),0,deck.pages.length-1);
  if(deck.player){
    if(FILES&&typeof FILES.presentationSet==='function')return FILES.presentationSet(media,next,options);
    return deck.player.go(next,options).then(()=>{if(options.signal?.aborted||options.isCurrent&&options.isCurrent()!==true)return false;deck.current=next;media.sourceRevision=(Number(media.sourceRevision)||0)+1;MEDIA?.touch?.();return true;});
  }
  if(next===Number(deck.current)) return true;
  /* ArenaFiles normally owns imported document records. The Clip, however,
     already owns all of its in-memory slide Files. Keep performance navigation
     available if the optional Files-panel module was unavailable or restored
     later than the Composition; an existing Presentation Clip must not grow a
     dead clicker merely because its library UI is absent. */
  if(FILES&&typeof FILES.presentationSet==='function')
    return !!FILES.presentationSet(media,next);
  const page=deck.pages[next];
  if(!page) return false;
  if(!page.url){
    if(!page.file||typeof URL==='undefined'||typeof URL.createObjectURL!=='function') return false;
    try { page.url=URL.createObjectURL(page.file); }
    catch(error){ return false; }
  }
  deck.current=next; media.video=page.url; media.poster=page.url;
  media.sourceRevision=(Number(media.sourceRevision)||0)+1;
  if(MEDIA&&typeof MEDIA.touch==='function') MEDIA.touch();
  return true;
}
function moveSelectedPresentation(target){
  const clip=selectedPresentationClip(),media=clip&&clip.media,deck=media&&media.presentation;
  if(!deck||!Array.isArray(deck.pages)||!deck.pages.length) return false;
  if(target!=='previous'&&target!=='next') return false;
  const current=clamp(Math.round(Number(deck.current)||0),0,deck.pages.length-1);
  const index=current+(target==='next'?1:-1);
  if(index<0||index>=deck.pages.length) return false;
  const finish=ready=>{
    if(!ready){msg(`${deck.title||'Presentation'}: slide image unavailable; import the document again`);return false;}
    if(!presentationClipPresent(clip)||clip.media!==media)return false;
    render.grid();render.layers();render.panel();msg(`${deck.title}: slide ${deck.current+1} of ${deck.pages.length}`);return true;
  };
  const result=setPresentationSlide(media,index,{isCurrent:()=>presentationClipPresent(clip)&&
    clip.media===media&&media.presentation===deck});
  return result&&typeof result.then==='function'?result.then(finish,error=>{msg(error.message||String(error));return false;}):finish(result);
}
function bindPresentationControls(root){
  if(!root) return;
  root.querySelectorAll(
    'button[data-presentation-step="previous"],button[data-presentation-step="next"]'
  ).forEach(button=>
    button.addEventListener('click',event=>{
      event.preventDefault(); event.stopPropagation();
      moveSelectedPresentation(button.dataset.presentationStep);
    }));
}

function commitLiveNumericEntry(cell){
  if(!cell) return false;
  const id=+cell.dataset.pid, p=AL.paramById(id); if(!p) return false;
  const row=cell.closest('.prow');
  const input=row&&row.querySelector('input[type=range].pbind');
  const display=liveRangePresentation(input,p);
  const multiplier=Number.isFinite(display.multiplier)&&display.multiplier!==0
    ? display.multiplier : (p.min===0&&p.max===1?100:1);
  const precision=Number.isInteger(display.precision)?display.precision:null;
  const shown=Number(p.value)*multiplier;
  const typed=prompt(p.name||'Value',precision==null?String(shown):shown.toFixed(precision));
  if(typed==null) return false;
  let next=EN.evalNumeric(typed,null); if(next==null) return false;
  if(precision!=null) next=+Number(next).toFixed(precision);
  next=clamp(next/multiplier,p.min??0,p.max??1);
  AL.setParam(id,next);
  cell.textContent=fmt(p,next,display);
  if(input) input.value=Math.round(((next-(p.min??0))/(((p.max??1)-(p.min??0))||1))*1000);
  return true;
}

/* two-way binding for every .pbind in a scope */
function bindParams(scope){
  scope.querySelectorAll('select.pbind').forEach(el=>{
    el.addEventListener('change',()=>AL.setParam(+el.dataset.pid, el.value)); });
  scope.querySelectorAll('input.ptext, textarea.ptext').forEach(el=>{
    el.addEventListener('change',()=>AL.setParam(+el.dataset.pid, el.value)); });
  scope.querySelectorAll('.pval[data-pid]').forEach(cell=>{
    cell.addEventListener('click',()=>commitLiveNumericEntry(cell));
    cell.addEventListener('keydown',event=>{
      if(event.key!=='Enter') return;
      event.preventDefault(); commitLiveNumericEntry(cell);
    });
  });
  scope.querySelectorAll('button.pbind').forEach(el=>{
    el.addEventListener('click',()=>{
      const id=+el.dataset.pid;
      if(el.dataset.kind==='trig'){ AL.triggerParam(id); return; }
      if(el.dataset.kind==='color'){
        const p=AL.paramById(id); if(p) openColorPicker(p,el);
        return;
      }
      if(el.dataset.kind==='file'){
        const p=AL.paramById(id);
        const next=prompt('Image path visible to Resolume Arena', p&&p.value ? String(p.value) : '');
        if(next!=null) AL.setParam(id,next.trim());
        return;
      }
      const p=AL.paramById(id); const nv=!(p&&p.value);
      AL.setParam(id,nv); el.classList.toggle('on',nv); el.textContent=nv?'On':'Off'; }); });
  scope.querySelectorAll('.cswatch[data-pid]').forEach(el=>
    el.addEventListener('contextmenu',e=>{
      e.preventDefault(); e.stopPropagation(); AL.resetParam(+el.dataset.pid);
    }));
  scope.querySelectorAll('input[type=range].pbind').forEach(el=>{
    const min=+el.dataset.min, max=+el.dataset.max;
    const push=()=>{
      const v = min + (+el.value/1000)*(max-min);
      AL.setParam(+el.dataset.pid, v);
      const cell=scope.querySelector(`.val[data-pid="${el.dataset.pid}"]`);
      const p=AL.paramById(+el.dataset.pid)||{min,max,valuetype:'ParamRange'};
      const display=liveRangePresentation(el,p), valueText=fmt(p,v,display);
      if(cell) cell.textContent=valueText;
      if(display.control==='hue') el.setAttribute('aria-valuetext',valueText);
    };
    el.addEventListener('input',push);
  });
  scope.querySelectorAll('.stp[data-pid]').forEach(el=>el.addEventListener('click',()=>{
    const r=scope.querySelector(`input[type=range][data-pid="${el.dataset.pid}"]`); if(!r) return;
    r.value = clamp(+r.value + (+el.dataset.d)*10, 0, 1000);
    r.dispatchEvent(new Event('input')); }));
  scope.querySelectorAll('.pdial').forEach(k=>k.addEventListener('mousedown',e=>{
    e.preventDefault();
    const y=e.clientY, r0=parseFloat(k.style.getPropertyValue('--rot'))||0;
    const min=+k.dataset.min, max=+k.dataset.max, id=+k.dataset.pid;
    const mv=ev=>{ const rot=clamp(r0+(y-ev.clientY)*2,-135,135);
      k.style.setProperty('--rot',rot+'deg');
      AL.setParam(id, min + ((rot+135)/270)*(max-min)); };
    const up=()=>{removeEventListener('mousemove',mv);removeEventListener('mouseup',up);};
    addEventListener('mousemove',mv); addEventListener('mouseup',up); }));
  /* Live effect mutations use the row's explicit track. Names are insufficient:
     audio/video Distortion are two plugins with two REST address spaces. */
  scope.querySelectorAll('[data-live-fx-remove]').forEach(el=>el.addEventListener('click',()=>{
    const row=el.closest('[data-live-fxscope]'); if(!row) return;
    const track=effectTrack(row.dataset.liveFxtrack);
    AL.cmd.removeEffect(row.dataset.liveFxscope,+el.dataset.liveFxRemove,track)
      .then(()=>msg(track+' effect removed')).catch(x=>msg(x.message));
  }));
  scope.querySelectorAll('[data-live-fxi]').forEach(row=>{
    row.addEventListener('dragstart',e=>{
      if(e.target.closest('button')){ e.preventDefault(); return; }
      e.dataTransfer.setData('text/plain',JSON.stringify({
        kind:'fxmove', live:true, i:+row.dataset.liveFxi, scope:row.dataset.liveFxscope,
        track:effectTrack(row.dataset.liveFxtrack), name:row.dataset.liveFxname
      }));
    });
    row.addEventListener('dragover',e=>e.preventDefault());
    row.addEventListener('drop',async e=>{
      e.preventDefault(); e.stopPropagation();
      let item; try{ item=JSON.parse(e.dataTransfer.getData('text/plain')); }catch{ return; }
      if(item&&item.domain==='lighting') return msg('GSL5 lighting effects attach to Clip Slots, not Arena effect chains.');
      const scopePath=row.dataset.liveFxscope, track=effectTrack(row.dataset.liveFxtrack);
      if(effectTrack(item.track)!==track) return msg('That is a '+effectTrack(item.track)+' effect; drop it in '+track+' effects.');
      if(item.kind==='fxmove' && item.live && item.scope===scopePath){
        AL.cmd.moveEffect(scopePath,item.i,+row.dataset.liveFxi,track,item.name)
          .then(r=>msg(r&&r.reinserted?'Effect moved; parameters reset by Arena':'Effect moved'))
          .catch(x=>msg(x.message));
      } else if(item.kind==='effect'){
        try {
          const result=await addEffectItemLive(scopePath,item,track,+row.dataset.liveFxi,e.altKey);
          msg(result.altWarning || '+ '+result.name+(result.preset?': '+result.preset:'')+' ('+track+')');
        } catch(x){ msg(x.message); }
      }
    });
    row.addEventListener('keydown',e=>{
      if(e.target!==row || !e.altKey || (e.key!=='ArrowUp' && e.key!=='ArrowDown')) return;
      const scopePath=row.dataset.liveFxscope, track=effectTrack(row.dataset.liveFxtrack);
      const peers=[...scope.querySelectorAll('[data-live-fxi]')].filter(el=>
        el.dataset.liveFxscope===scopePath && effectTrack(el.dataset.liveFxtrack)===track);
      const from=+row.dataset.liveFxi;
      const to=Math.max(0,Math.min(peers.length-1,from+(e.key==='ArrowUp'?-1:1)));
      if(to===from) return;
      e.preventDefault(); e.stopPropagation(); rememberEffectFocus(row,to);
      AL.cmd.moveEffect(scopePath,from,to,track,row.dataset.liveFxname)
        .then(r=>msg(r&&r.reinserted?'Effect moved; parameters reset by Arena':'Effect moved'))
        .catch(x=>{ pendingEffectFocus=null; msg(x.message); });
    });
  });
  scope.querySelectorAll('[data-fxdrop]').forEach(el=>{
    el.addEventListener('dragover',e=>{e.preventDefault(); el.classList.add('drop');});
    el.addEventListener('dragleave',()=>el.classList.remove('drop'));
    el.addEventListener('drop',async e=>{
      e.preventDefault(); el.classList.remove('drop');
      const d=e.dataTransfer.getData('text/plain'); if(!d) return;
      let item; try { item=JSON.parse(d); } catch(error){ return; }
      if(item&&item.domain==='lighting') return msg('GSL5 lighting effects attach to Clip Slots, not Arena effect chains.');
      if(!item || item.kind!=='effect') return;
      const track=effectTrack(el.dataset.fxtrack);
      if(effectTrack(item.track)!==track) return msg('That is a '+effectTrack(item.track)+' effect; drop it in '+track+' effects.');
      try {
        const result=await addEffectItemLive(el.dataset.fxdrop,item,track,null,e.altKey);
        msg(result.altWarning || '+ '+result.name+(result.preset?': '+result.preset:'')+' ('+track+')');
      } catch(x){ msg(x.message); }
    });
  });
}
/* push live parameter updates into whatever is on screen */
function applyParamToDom(id, p){
  const sel = $(`#pbody select.pbind[data-pid="${id}"]`);
  if(sel && document.activeElement!==sel && p.value!=null) sel.value = p.value;
  const txt = $(`#pbody .ptext[data-pid="${id}"]`);
  if(txt && document.activeElement!==txt && p.value!=null) txt.value = p.value;
  const btn = $(`#pbody button.pbind[data-pid="${id}"][data-kind="bool"]`);
  if(btn){ btn.classList.toggle('on',!!p.value); btn.textContent=p.value?'On':'Off'; }
  const color = $(`#pbody button.pbind[data-pid="${id}"][data-kind="color"]`);
  if(color){
    const word=liveColorWord(p.value), chip=color.querySelector('.cchip'), label=color.querySelector('.cval');
    if(chip) chip.style.background=EN.colorCss(word);
    if(label) label.textContent=liveColorValue(word);
    color.title=`${p.value} · alpha ${Math.round(EN.colorParts(word).a/2.55)}%`;
    syncOpenPicker(p);
  }
  const file = $(`#pbody button.pbind[data-pid="${id}"][data-kind="file"]`);
  if(file){
    const value=file.querySelector('.imagevalue'); if(value) value.textContent=imageParamLabel(p.value);
    file.title=p.value || 'Click to enter an image path visible to Arena';
  }
  const rng = $(`#pbody input[type=range].pbind[data-pid="${id}"]`);
  if(rng && document.activeElement!==rng){
    const min=+rng.dataset.min, max=+rng.dataset.max;
    rng.value = Math.round(((p.value-min)/((max-min)||1))*1000);
    const display=liveRangePresentation(rng,p), valueText=fmt(Object.assign({min,max},p),p.value,display);
    const cell=$(`#pbody .val[data-pid="${id}"]`); if(cell) cell.textContent=valueText;
    if(display.control==='hue') rng.setAttribute('aria-valuetext',valueText);
  }
  const dial = $(`#pbody .pdial[data-pid="${id}"]`);
  if(dial){ const min=+dial.dataset.min, max=+dial.dataset.max;
    dial.style.setProperty('--rot', (-135 + ((p.value-min)/((max-min)||1))*270)+'deg'); }
}

/* Arena shows a contextual tab set */
/* =========================================================================
   ENGINE ROW BINDING
   Reads and writes go through EN.setParam, so anything else showing the same
   parameter repaints on the same notification.
   ========================================================================= */
function bindEngineRows(root){
  const P_ = el => EN.param(el.dataset.ep);

  /* Register the existing File for this session before committing the Mask/UV
     parameter. The resource registry owns its temporary capability; selecting
     it does not write another copy of the image. */
  const registerFileImage = async file => {
    if(!file || !FX || !FX.registerImage) return '';
    if(file.type && !file.type.startsWith('image/')){
      msg('Image parameters accept still images.');
      return '';
    }
    if(FILES && FILES.persistImage){
      try {
        const saved=await FILES.persistImage(file);
        if(saved && saved.id) return saved.id;
      } catch(err){
        msg('Could not save this image for reload. Using it for this session only.');
      }
    }
    return FX.registerImage(file);
  };
  const registerResourceFile = async (p,file) => {
    if(!p || !file || p.resourceType!=='lut3d' || !FX || !FX.registerLUT) return null;
    if(!/\.cube$/i.test(file.name||'')){
      msg('LUT 3D accepts .cube files.'); return null;
    }
    if(FILES && FILES.persistLUT){
      try {
        const saved=await FILES.persistLUT(file);
        if(saved && saved.id) return {id:saved.id,name:saved.name};
      } catch(err){
        /* Storage is optional. A quota/private-mode failure must not make a
           valid LUT unusable for the current performance. */
        msg((err.message || 'Could not save this LUT.')+' Using it for this session only.');
      }
    }
    const text=await file.text();
    /* The filename is a display label, not an identity. Two touring folders
       routinely contain different `look.cube` files; a unique key keeps the
       pixels and Undo history independent. */
    const unique=(globalThis.crypto && typeof globalThis.crypto.randomUUID==='function')
      ? globalThis.crypto.randomUUID()
      : Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
    const id='lut:session:'+unique+':'+file.name;
    const result=FX.registerLUT(id,text);
    if(result && result.error){ msg(result.error); return null; }
    msg(window.OpenLiveSessionPolicy&&OpenLiveSessionPolicy.sessionOnly
      ? 'LUT available for this session.' : 'IndexedDB is unavailable; this LUT is session-only.');
    return {id,name:file.name,data:text};
  };
  const commitResource = (p,record) => {
    if(!p || !record) return;
    EN.editParameterState('Load LUT 3D',[p],opts=>{
      p.resourceName=record.name || '';
      if(record.data) p.resourceData=record.data; else delete p.resourceData;
      EN.setParam(p,record.id,opts);
    });
    refreshEngineRows();
  };

  root.querySelectorAll('input[type=range].ebind').forEach(r=>{
    let gesture=null;
    const finishGesture=()=>{
      if(!gesture) return;
      EN.endParamGesture(gesture); gesture=null;
    };
    r.addEventListener('pointerdown',e=>{
      if(e.button!==0) return;
      const p=P_(r); if(!p) return;
      gesture=EN.beginParamGesture(p);
      try { r.setPointerCapture(e.pointerId); } catch(_) {}
    });
    r.addEventListener('input',()=>{
      const p=P_(r); if(!p) return;
      EN.applyNormalised(p, (+r.value)/1000, gesture ? {noUndo:true} : undefined);
      if(p.control==='hue') r.setAttribute('aria-valuetext',efmt(p));
    });
    r.addEventListener('pointerup',finishGesture);
    r.addEventListener('pointercancel',finishGesture);
    r.addEventListener('lostpointercapture',finishGesture);
  });
  root.querySelectorAll('select.ebind').forEach(s=>
    s.addEventListener('change',()=>{
      const p=P_(s); if(!p) return;
      const typed=Array.isArray(p.options) ? p.options.find(option=>String(option)===s.value) : undefined;
      const next=typed===undefined?s.value:typed;
      if(!S.live && p===EN.comp().trigger.direction){ EN.setGlobalDirection(next); return; }
      EP(p,next);
    }));
  root.querySelectorAll('.etext').forEach(t=>{
    const commit=()=>commitEngineTextInput(t);
    t.addEventListener('change',commit);
    t.addEventListener('blur',commit);
    t.addEventListener('keydown',event=>{
      if(event.key!=='Enter' || event.isComposing) return;
      if(t.tagName==='TEXTAREA' && !event.ctrlKey && !event.metaKey) return;
      event.preventDefault();
      commit();
      t.blur();
    });
  });
  root.querySelectorAll('button.ebind').forEach(b=>
    b.addEventListener('click',e=>{
      const p=P_(b); if(!p) return;
      /* A colour swatch is a button and must NOT fall through to the generic
         "increment the value" branch below — that branch would add 1 to a
         packed 0xAARRGGBB word, i.e. nudge the blue channel by one and call it
         a click. It opens the picker, which is what parameters.htm shows. */
      if(b.dataset.kind==='color'){ e.stopPropagation(); openColorPicker(p, b); return; }
      if(b.dataset.kind==='image'){
        e.stopPropagation();
        const picker=root.querySelector(`input.imagefile[data-ep="${b.dataset.ep}"]`);
        if(picker) picker.click();
        return;
      }
      if(b.dataset.kind==='resource'){
        e.stopPropagation();
        const picker=root.querySelector(`input.resourcefile[data-ep="${b.dataset.ep}"]`);
        if(picker) picker.click();
        return;
      }
      if(b.dataset.kind==='event') EN.triggerEvent(p);
      else if(b.dataset.kind==='choice'){
        const next=b.dataset.value;
        if(p===EN.comp().trigger.direction) EN.setGlobalDirection(next);
        else EP(p,next);
      }
      else if(b.dataset.kind==='bool') EP(p, !p.value);
      else EP(p, (p.value||0)+1);
    }));
  root.querySelectorAll('input.imagefile[data-ep]').forEach(input=>
    input.addEventListener('change',async ()=>{
      const p=P_(input), file=input.files&&input.files[0];
      if(!p || !file || !FX || !FX.registerImage) return;
      const id=await registerFileImage(file);
      if(!id) return;
      EP(p,id);                         // one value write / one undo entry
      refreshEngineRows();
    }));
  root.querySelectorAll('input.resourcefile[data-ep]').forEach(input=>
    input.addEventListener('change',async ()=>{
      const p=P_(input),file=input.files&&input.files[0];
      const record=await registerResourceFile(p,file);
      if(record) commitResource(p,record);
    }));
  root.querySelectorAll('button.imagebind[data-ep]').forEach(button=>{
    button.addEventListener('dragover',e=>{ e.preventDefault(); e.stopPropagation(); button.classList.add('drop'); });
    button.addEventListener('dragleave',()=>button.classList.remove('drop'));
    button.addEventListener('drop',async e=>{
      e.preventDefault(); e.stopPropagation(); button.classList.remove('drop');
      const p=P_(button); if(!p || !FX || !FX.registerImage) return;
      const file=e.dataTransfer.files&&e.dataTransfer.files[0];
      if(file){
        const id=await registerFileImage(file);
        if(id){ EP(p,id); refreshEngineRows(); }
        return;
      }
      let data; try{ data=JSON.parse(e.dataTransfer.getData('text/plain')); }catch(err){ return; }
      if(!data || data.kind!=='media' || !data.id) return;
      const media=MEDIA&&MEDIA.find(data.id);
      if(media && media.mediaKind!=='image') return msg('Image parameters accept still images.');
      FX.registerImage(data.id,data.id);
      EP(p,data.id); refreshEngineRows();
    });
  });
  root.querySelectorAll('button.resourcebind[data-ep]').forEach(button=>{
    button.addEventListener('dragover',e=>{ e.preventDefault(); e.stopPropagation(); button.classList.add('drop'); });
    button.addEventListener('dragleave',()=>button.classList.remove('drop'));
    button.addEventListener('drop',async e=>{
      e.preventDefault(); e.stopPropagation(); button.classList.remove('drop');
      const p=P_(button),file=e.dataTransfer.files&&e.dataTransfer.files[0];
      const record=await registerResourceFile(p,file);
      if(record) commitResource(p,record);
    });
  });
  /* Color keeps its documented direct reset gesture. Image parameters use the
     full parameter context menu through the delegated handler below. */
  root.querySelectorAll('.cswatch[data-ep]').forEach(s=>
    s.addEventListener('contextmenu',e=>{
      e.preventDefault(); e.stopPropagation();
      const p=P_(s); if(p){ EN.reset(p); render.panel(); }
    }));
  /* THE NUDGE STEP HAS TO SUIT THE PARAMETER, NOT THE RANGE.
     One generic (max-min)/100 drove every +/- button in the app, which is
     defensible for a 0..1 fader and nonsense everywhere else: clip Duration is
     0.1..360, so a nudge moved it 3.6 SECONDS; BPM-Sync beats is 1..512, so a
     nudge moved it 5.1 BEATS and could never land on a musical value at all.
     Beats must move by whole beats and durations by a tenth of a second — the
     manual's own description of what these buttons are for. */
  /* ORDER MATTERS, and testing against the engine's real ranges is what proved
     it. Matching on the NAME first got 'Beat Snap' wrong: it is a 0..1 choice,
     not a beat count, so a step of 1 jumped its whole range. Layer Transition
     Duration is an actual 0..10 second ParamRange in both the offline model and
     the captured Arena schema, and therefore correctly reaches the time-name
     rule below for 0.1 second nudges. The parameter's SHAPE is still decided
     before its name is consulted. */
  const nudgeStep = p => {
    const lo = p.min ?? 0, hi = p.max ?? 1, span = hi - lo;
    const whole = Number.isInteger(lo) && Number.isInteger(hi);
    /* Wide integer ranges move by one of whatever they count — beats, BPM,
       pixels, layer and column counts, fixture channels. */
    if(whole && span > 4) return 1;
    /* Normalised 0..1 and bipolar -1..1 faders, whatever they are called. */
    if(span <= 2) return 0.01;
    /* Only now does the name matter, and only for genuinely wide ranges: clip
       Duration is 0.1..360 seconds and must move in tenths. */
    if(/beat/i.test(p.name || '')) return 1;
    if(/duration|time|seconds/i.test(p.name || '')) return 0.1;
    if(span <= 20) return 0.1;
    if(span <= 400) return 1;
    return Math.round(span / 100);                  /* very wide, e.g. 0..16384 px */
  };
  root.querySelectorAll('.stp[data-ep]').forEach(s=>
    s.addEventListener('click',()=>{
      const p=P_(s); if(!p) return;
      const step=nudgeStep(p)*(+s.dataset.d);
      /* Floating-point addition drifts (0.1+0.2), and a Duration reading
         2.9000000000000004 after three clicks is the same class of lie as a
         fake number. Snap to the step's own precision. */
      const dp=Math.max(0, -Math.floor(Math.log10(Math.abs(step)||1)));
      EP(p, +( (p.value||0) + step ).toFixed(dp));
    }));
  /* parameters.htm > Math — "type 1920 / 3 and Resolume will do the math" */
  root.querySelectorAll('.val.ev').forEach(v=>
    v.addEventListener('click',()=>{
      const p=P_(v); if(!p) return;
      const multiplier=Number.isFinite(p.multiplier) ? p.multiplier
        : (p.min===0&&p.max===1 ? 100 : 1);
      const precision=Number.isInteger(p.precision) ? p.precision : null;
      const displayed=Number(p.value)*multiplier;
      const typed = prompt(p.name, precision==null ? String(displayed) : displayed.toFixed(precision));
      if(typed==null) return;
      let n = EN.evalNumeric(typed, null); if(n==null) return;
      n/=multiplier;
      EP(p, n);
    }));
  /* parameters.htm > Reset to Default — right click the name or the slider */
  root.querySelectorAll('label[data-ep], input[type=range].ebind').forEach(el=>
    el.addEventListener('contextmenu',e=>{
      /* The label and slider share the full Parameter menu. Reset remains its
         first action; swallowing this event and resetting immediately made
         every shortcut/mapping action in the delegated menu unreachable. */
      openParameterContextMenu(e,el.closest('.prow'));
    }));
  /* compound sliders — parameters.htm */
  root.querySelectorAll('.tw.x').forEach(t=>
    t.addEventListener('click',()=>{
      const sub=root.querySelector(`.sub[data-sub="${t.dataset.x}"]`);
      if(sub){ sub.hidden=!sub.hidden; t.textContent = sub.hidden?'▶':'▼'; }
    }));

  /* the animation cog — parameter-animation.htm */
  root.querySelectorAll('.cog[data-ep]').forEach(c=>
    c.addEventListener('click',e=>{
      const p=P_(c); if(!p) return;
      /* Keep this explicit call at the binding seam: it makes it impossible
         for a future refactor to reconnect the cog to an all-scope constant. */
      if(!animationModesForParameter(p).length) return;
      e.preventDefault(); e.stopPropagation();
      openParameterAnimationMenu(p,c);
    }));

  /* dashboard: drag a parameter row onto a dial */
  /* Only real Engine Parameter rows can be dragged onto Dashboard dials.
     Static rows (notably the Presentation Clip clicker) share the .prow.eb
     layout classes but have no data-ep. Marking those rows draggable gave the
     whole slide-control window a grab cursor and emitted a bogus undefined
     Parameter payload from any blank-space drag. */
  root.querySelectorAll('.prow.eb[data-ep]').forEach(row=>{
    row.setAttribute('draggable','true');
    row.addEventListener('dragstart',e=>e.dataTransfer.setData('text/plain',
      JSON.stringify({kind:'param', id:row.dataset.ep})));
  });
  /* dashboard.htm: the generated label is only a starting point; double-click
     the name to edit it. Keyboard users get the same editor with Enter/F2. */
  root.querySelectorAll('.dash-name[data-dash-name]').forEach(name=>{
    const begin=()=>{
      if(name.querySelector('input')) return;
      const p=EN.param(name.dataset.dashName); if(!p) return;
      const input=document.createElement('input');
      input.className='dash-name-editor'; input.type='text'; input.value=String(EN.val(p));
      input.setAttribute('aria-label','Quick Control dial name'); name.replaceChildren(input);
      let done=false;
      const finish=cancel=>{
        if(done) return; done=true;
        if(!cancel && input.value!==String(EN.val(p))) EP(p,input.value);
        render.panel();
      };
      input.addEventListener('keydown',event=>{
        if(event.key==='Enter'){ event.preventDefault(); finish(false); }
        else if(event.key==='Escape'){ event.preventDefault(); finish(true); }
      });
      input.addEventListener('blur',()=>finish(false));
      input.focus(); input.select();
    };
    name.addEventListener('dblclick',begin);
    name.addEventListener('keydown',event=>{
      if(event.key!=='Enter'&&event.key!=='F2') return;
      event.preventDefault(); begin();
    });
  });
  root.querySelectorAll('.dial[data-dial]').forEach(d=>{
    d.addEventListener('dragover',e=>{ e.preventDefault(); d.classList.add('over'); });
    d.addEventListener('dragleave',()=>d.classList.remove('over'));
    d.addEventListener('drop',e=>{
      e.preventDefault(); d.classList.remove('over');
      let data; try{ data=JSON.parse(e.dataTransfer.getData('text/plain')); }catch{ return; }
      if(!data || data.kind!=='param') return;
      moveParameterToDashboard(d.dataset.dashhome,+d.dataset.dial,data.id);
      render.panel();
    });
  });
  root.querySelectorAll('.k.edial').forEach(k=>
    k.addEventListener('pointerdown',e=>{
      if(e.button!==0 || e.isPrimary===false) return;
      e.preventDefault();
      const p=EN.param(k.dataset.ep); if(!p) return;
      const pointerId=e.pointerId, y0=e.clientY, v0=p.value;
      const gesture=EN.beginParamGesture(p,'Dashboard Dial');
      let finished=false;
      const mv=e2=>{
        if(e2.pointerId!==pointerId) return;
        EN.setParam(p,clamp(v0+(y0-e2.clientY)/150,0,1),{noUndo:true});
      };
      const finish=e2=>{
        if(finished || (e2 && e2.pointerId!=null && e2.pointerId!==pointerId)) return;
        finished=true;
        k.removeEventListener('pointermove',mv);
        k.removeEventListener('pointerup',finish);
        k.removeEventListener('pointercancel',finish);
        k.removeEventListener('lostpointercapture',finish);
        EN.endParamGesture(gesture);
      };
      k.addEventListener('pointermove',mv);
      k.addEventListener('pointerup',finish);
      k.addEventListener('pointercancel',finish);
      k.addEventListener('lostpointercapture',finish);
      try { k.setPointerCapture(pointerId); } catch(_) {}
    }));

  /* effects: bypass, remove, reorder, drop target */
  root.querySelectorAll('[data-fxbyp]').forEach(b=>
    b.addEventListener('click',()=>{
      const scope=scopeFromHome(b.closest('.fx').dataset.fxscope);
      const track=effectTrack(b.dataset.fxtrack);
      const fx=scope && scope[track] && scope[track].effects[+b.dataset.fxbyp];
      if(fx) EP(fx.bypassed, !EN.val(fx.bypassed));
    }));
  root.querySelectorAll('[data-fxrm]').forEach(b=>
    b.addEventListener('click',()=>{
      const scope=scopeFromHome(b.closest('.fx').dataset.fxscope);
      const track=effectTrack(b.dataset.fxtrack);
      if(scope) EN.removeEffect(scope, +b.dataset.fxrm, track==='audio');
      render.panel();
    }));
  root.querySelectorAll('.fx[draggable]').forEach(fx=>{
    fx.addEventListener('dragstart',e=>{
      if(e.target.closest('button')){ e.preventDefault(); return; }
      e.dataTransfer.setData('text/plain',JSON.stringify({kind:'fxmove', i:+fx.dataset.fxi,
        scope:fx.dataset.fxscope,track:effectTrack(fx.dataset.fxtrack)}));
    });
    fx.addEventListener('dragover',e=>e.preventDefault());
    fx.addEventListener('drop',async e=>{
      e.preventDefault(); e.stopPropagation();
      let d; try{ d=JSON.parse(e.dataTransfer.getData('text/plain')); }catch{ return; }
      if(d&&d.domain==='lighting') return msg('GSL5 lighting effects attach to Clip Slots, not video/audio effect chains.');
      const scope=scopeFromHome(fx.dataset.fxscope); if(!scope) return;
      const track=effectTrack(fx.dataset.fxtrack);
      if(effectTrack(d.track)!==track) return msg('That is a '+effectTrack(d.track)+' effect; drop it in '+track+' effects.');
      if(d.kind==='fxmove' && d.scope===fx.dataset.fxscope)
        EN.moveEffect(scope, d.i, +fx.dataset.fxi, track==='audio');
      else if(d.kind==='sliceTransform') addSliceTransform(scope, d);
      else if(d.kind==='effect'){
        try { const added=await addEffectItemOffline(scope,d,track,+fx.dataset.fxi,e.altKey);
          if(effectPresetNotice(added)) msg(effectPresetNotice(added).slice(3)); }
        catch(x){ msg(x.message); }
      }
      render.panel();
    });
    fx.addEventListener('keydown',e=>{
      if(e.target!==fx || !e.altKey || (e.key!=='ArrowUp' && e.key!=='ArrowDown')) return;
      const scope=scopeFromHome(fx.dataset.fxscope); if(!scope) return;
      const track=effectTrack(fx.dataset.fxtrack);
      const peers=[...root.querySelectorAll('.fx[data-fxi]')].filter(el=>
        el.dataset.fxscope===fx.dataset.fxscope && effectTrack(el.dataset.fxtrack)===track);
      const from=+fx.dataset.fxi;
      const to=Math.max(0,Math.min(peers.length-1,from+(e.key==='ArrowUp'?-1:1)));
      if(to===from) return;
      e.preventDefault(); e.stopPropagation(); rememberEffectFocus(fx,to);
      EN.moveEffect(scope,from,to,track==='audio');
      render.panel();
    });
  });
  root.querySelectorAll('[data-fxdrop]').forEach(z=>{
    z.addEventListener('dragover',e=>{ e.preventDefault(); z.classList.add('over'); });
    z.addEventListener('dragleave',()=>z.classList.remove('over'));
    z.addEventListener('drop',async e=>{
      e.preventDefault(); z.classList.remove('over');
      let d; try{ d=JSON.parse(e.dataTransfer.getData('text/plain')); }catch{ return; }
      if(d&&d.domain==='lighting') return msg('GSL5 lighting effects attach to Clip Slots, not video/audio effect chains.');
      const scope=scopeFromHome(z.dataset.fxdrop);
      const track=effectTrack(z.dataset.fxtrack);
      /* a screen or slice dragged out of the Slices panel [transform.htm] */
      if(scope && d && d.kind==='sliceTransform' && track==='video') addSliceTransform(scope, d);
      /* effects.htm — "Hold down ALT while dropping an effect to apply it with
         its opacity turned all the way down." */
      else if(scope && d && d.kind==='effect' && effectTrack(d.track)!==track)
        return msg('That is a '+effectTrack(d.track)+' effect; drop it in '+track+' effects.');
      else if(scope && d && d.kind==='effect' && pluginNameOf(d)){
        try { const added=await addEffectItemOffline(scope,d,track,null,e.altKey);
          if(effectPresetNotice(added)) msg(effectPresetNotice(added).slice(3)); }
        catch(x){ msg(x.message); }
      }
      render.panel();
    });
    z.addEventListener('dblclick',()=>{
      const name=prompt('Add effect'); if(!name) return;
      const scope=scopeFromHome(z.dataset.fxdrop);
      const track=effectTrack(z.dataset.fxtrack);
      const catalog=track==='audio' ? AUDIO_EFFECTS : VIDEO_EFFECTS;
      const match=catalog.find(v=>v.toLowerCase().startsWith(name.toLowerCase()));
      if(scope&&match){ EN.addEffect(scope, match, {audio:track==='audio'}); render.panel(); }
    });
  });
}
function scopeFromHome(home){
  const all=[EN.comp(), ...EN.groups(), ...EN.layers()];
  const hit=all.find(n=>n.home===home); if(hit) return hit;
  const k=EN.clip(S.selLayer,S.selCol);
  return (k && k.home===home) ? k : null;
}
/* A Parameter inherits animation sources and Dashboard ownership from the
   panel that actually contains it.  This must be a deepest, segment-boundary
   match: `/composition` is a prefix of every document address, and Layer 1 is
   a textual prefix of Layer 10.  Effects and Sources deliberately have no
   special case here—their longer homes remain below their Clip, Layer, Group
   or Composition owner and therefore inherit that exact scope.

   Deck and Column paths are an important negative case. They are addressable
   Parameters, but neither owns one of the four animation/Dashboard panels in
   the manual. A Clip nested below a Deck is collected first and still wins. */
function parameterOwnerScope(p){
  if(!p || !p.home) return null;
  const path=String(p.home);
  if(/^\/preview\/browser(?:\/|$)/.test(path))
    return {kind:'preview',home:'/preview/browser'};

  const clips=[];
  const decks=EN.decks ? EN.decks() : (EN.doc&&EN.doc.decks)||[];
  (decks||[]).forEach(deck=>{
    const values=deck&&deck.clips&&typeof deck.clips.values==='function'
      ? [...deck.clips.values()] : Array.isArray(deck&&deck.clips) ? deck.clips : [];
    values.forEach(clip=>{ if(clip&&!clips.includes(clip)) clips.push(clip); });
  });
  const selected=EN.clip&&EN.clip(S.selLayer,S.selCol);
  if(selected&&!clips.includes(selected)) clips.push(selected);
  const composition=EN.comp&&EN.comp();
  const nodes=[...clips,...(EN.groups?EN.groups():[]),...(EN.layers?EN.layers():[]),composition]
    .filter(node=>node&&node.home);
  const boundary=(home)=>path===home || path.startsWith(home+'/');
  let matches=nodes.filter(node=>boundary(String(node.home)));
  /* A direct /composition/columns/... or /composition/decks/... Parameter is
     not a Composition-panel Parameter. Preserve only a real nested Clip. */
  if(/^\/composition\/(?:columns|decks)(?:\/|$)/.test(path))
    matches=matches.filter(node=>node.kind==='clip');
  matches.sort((a,b)=>String(b.home).length-String(a.home).length);
  return matches[0]||null;
}

/* parameter-animation.htm: the cog is contextual. Composition FFT and
   External FFT are common; Clip Position is Clip-only; the matching
   Clip/Layer/Group FFT exists only in that panel; Crossfader Phase belongs to
   Composition, Group and Layer but not Clip. PARAM_ANIMATION is the shared
   documented superset, while this helper is the sole scope filter. */
function animationModesForParameter(p){
  const scope=parameterOwnerScope(p);
  if(!scope) return [];
  const common=['Off','Timeline','BPM Sync','Composition FFT','External FFT'];
  const allowedByScope={
    composition:[...common,'Crossfader Phase'],
    group:[...common,'Crossfader Phase','Group FFT'],
    layer:[...common,'Crossfader Phase','Layer FFT'],
    clip:[...common,'Clip Position','Clip FFT'],
    preview:[...common]
  };
  const allowed=new Set(allowedByScope[scope.kind]||[]);
  return ['Off',...(PARAM_ANIMATION||[]).filter(mode=>mode!=='Off'&&allowed.has(mode))];
}

function scopeHomeFor(p){
  const owner=parameterOwnerScope(p);
  if(!owner || !['composition','group','layer','clip'].includes(owner.kind)) return null;
  return owner ? owner.home : null;
}

function parameterDashboardEligible(p){
  if(!p || p.transient || p.action || p.unwired || p.disabled || !scopeHomeFor(p)) return false;
  return ['range','number','bool','choice','color'].includes(p.type);
}

function chooseParameterAnimation(p,choice){
  if(!p) return false;
  if(choice.kind==='dashboard'){
    const home=scopeHomeFor(p);
    if(!home || !parameterDashboardEligible(p)) return false;
    const changed=moveParameterToDashboard(home,choice.dial,p);
    render.panel();
    return changed;
  }
  if(choice.kind==='off'){
    if(p.dash){
      EN.unlinkFromDashboard(p.dash.home,p.dash.dial,p.id);
    } else if(p.anim){
      EN.editParameterState('Stop '+p.name,[p],()=>EN.stopAnimation(p));
    }
    render.panel();
    return true;
  }
  let animation=true;
  const label=choice.kind==='envelope'
    ? ((p.anim&&p.anim.env?'Remove ':'Add ')+'Envelope: '+p.name)
    : 'Animate '+p.name;
  EN.editParameterState(label,[p],()=>{
    if(!ensureParameterAnimationPalette(p)){ animation=false; return; }
    if(choice.kind==='envelope')
      animation=EN.animate(p,Object.assign({},p.anim||{},
        {env:p.anim&&p.anim.env ? null : EN.newEnvelope()}));
    else animation=EN.animate(p,{mode:choice.mode});
  });
  if(!animation && p.type==='string') msg('Text animation needs at least two Basic values.');
  render.panel();
  return !!animation;
}

/* One item factory serves both the grey cog and the Parameter right-click
   submenu. `choice` plus the resolved `tick` is understood by buildDD as an
   ARIA radio item; the old `chosen` property painted no state at all. */
function parameterAnimationItems(p){
  if(!parameterAnimationEligible(p)) return [];
  const modes=animationModesForParameter(p);
  const items=modes.map(mode=>({
    l:mode,choice:'animationSource',
    tick:mode==='Off' ? !p.anim&&!p.dash : !!p.anim&&p.anim.mode===mode,
    fn:()=>chooseParameterAnimation(p,mode==='Off'?{kind:'off'}:{kind:'mode',mode})
  }));
  items.push({sep:1},{
    l:p.anim&&p.anim.env?'Remove Envelope':'Add Envelope',
    check:'animationEnvelope',tick:!!(p.anim&&p.anim.env),
    fn:()=>chooseParameterAnimation(p,{kind:'envelope'})
  });
  if(parameterDashboardEligible(p)){
    items.push({sep:1},...[1,2,3,4,5,6,7,8].map(number=>({
      l:'Dashboard → Dial '+number,uiLabel:'Quick Controls → Dial '+number,choice:'animationSource',
      tick:!!(p.dash&&p.dash.home===scopeHomeFor(p)&&p.dash.dial===number-1),
      fn:()=>chooseParameterAnimation(p,{kind:'dashboard',dial:number-1})
    })));
  }
  return items;
}

function openParameterAnimationMenu(p,opener){
  if(!p || !opener) return null;
  const items=parameterAnimationItems(p); if(!items.length) return null;
  const rect=opener.getBoundingClientRect();
  return buildDD(items,rect.right-200,rect.bottom+2,0,null,opener);
}

function buildTabs(){
  const tabs=[['pComp','Show'],['pLayer','Layer']];
  /* groups.htm — "the group panel will appear next to the layer panel" */
  const inGroup = S.live ? !!liveGroupContext(S.selLayer) : !!EN.groupOf(EN.layer(S.selLayer));
  if(inGroup) tabs.splice(1,0,['pGroup','Group']);
  if(S.selClip || (!S.live && EN.clip(S.selLayer,S.selCol))) tabs.push(['pClip','Clip']);
  tabs.push(['pColumn','Cue']);
  /* Unconditional, like Show / Layer / Cue — not conditional like Group and
     Clip above. An always-on tab must not move under the pointer.
     "Clip Time" is Resolume's own name for the panel (clip-time-panel.htm);
     the vocabulary rule forbids shortening it. */
  tabs.push(['pClipTime','Clip Time']);
  tabs.push(['pPresent','Present']);
  const el=$('#propTabs'); el.innerHTML='';
  tabs.forEach(([id,lbl])=>{
    const d=document.createElement('div');
    d.className='ptab'+(S.pane===id?' on':''); d.dataset.p=id; d.textContent=lbl;
    d.addEventListener('click',()=>switchPane(id));
    el.appendChild(d);
  });
}
function propertyPanelTitle(p){
  const liveGroup=S.live ? liveGroupContext(S.selLayer) : null;
  const offlineGroup=!S.live ? EN.groupOf(EN.layer(S.selLayer)) : null;
  const names={pComp: S.live&&AL.comp ? String(AL.val(AL.comp.name)||'Show')
      : !S.live&&EN.comp ? String(EN.val(EN.comp().name)||'Show') : 'Show',
    pGroup:liveGroup ? String(AL.val(liveGroup.group.name)||('Group '+liveGroup.index))
      : offlineGroup ? EN.displayName(offlineGroup) : 'Group', pLayer:layerName(S.selLayer),
    pClip:S.ctClip?(clipName(S.selLayer,S.selCol)||'empty'):'Clip', pColumn:cueUiName(S.selCol||1),
    /* Without these the field renders BLANK on the new tabs and stays
       editable: commitPropertyPanelTitle is an if-chain with no fallback,
       so typing a name and pressing Enter would write nothing, report
       nothing and leave no undo entry. */
    pClipTime:'Clip Time', pPresent:'Present'};
  return names[p]||'';
}
function syncPropertyPanelTitle(force){
  const title=$('#pTitle');
  if(title && (force || document.activeElement!==title)) title.value=propertyPanelTitle(S.pane);
  /* readOnly, NOT disabled: two code paths focus #pTitle as a last-resort
     target (after a clip-track removal, and after closing the browser
     preview), and a disabled input is not focusable — focus would drop to
     <body>. Cleared again on every pane that DOES have a commit branch,
     because #pTitle is one shared element. */
  if(title){
    const readOnly = S.pane==='pComp' || S.pane==='pClipTime' || S.pane==='pPresent';
    title.readOnly = readOnly;
    title.title = S.pane==='pComp' ? 'Shared Show name: double-click or press Enter to open Show Settings.'
      : readOnly ? 'This panel has no name to edit.' : '';
  }
}
function switchPane(p){ S.pane=p;
  syncPropertyPanelTitle(true); syncPropertyPanelMenuButton(); buildTabs();
  /* Panel generation can contain hundreds of Parameter rows. Let the current
     pointer/key task finish before replacing that tree, so triggering and
     selecting remain immediate even on a large Composition. The scheduler
     coalesces rapid Clip/Column navigation to the final inspector target. */
  render.panel();
}
function commitPropertyPanelTitle(){
  const v=$('#pTitle').value;
  if(S.pane==='pComp'){ syncPropertyPanelTitle(true); return; }
  if(!S.live){
    if(S.pane==='pLayer'){
      const layer=EN.layer(S.selLayer);
      if(layer){ EP(layer.name,v); syncPropertyPanelTitle(true); }
    }
    return;
  }
  if(S.pane==='pLayer'){ setLayerParam(S.selLayer,L=>L.name,v); }
  if(S.pane==='pGroup'){ const ref=liveGroupContext(S.selLayer); if(ref&&ref.group.name) AL.setParam(ref.group.name.id,v); }
  if(S.pane==='pColumn'){ const C=AL.column(S.selCol); if(C) AL.setParam(C.name.id, v); }
  if(S.pane==='pClip'){ const k=AL.clip(S.selLayer,S.selCol); if(k) AL.setParam(k.name.id, v); }
}
