function drawRotatedTransitionFrame(ctx,frame,axis,degrees,w,h,alpha,operation){
  if(!(alpha>0)) return;
  const spec=axis==='x'?{rotationX:degrees}:{rotationY:degrees};
  const rendered=TRANSFORM3D&&TRANSFORM3D.render
    ? TRANSFORM3D.render(frame,spec,w,h) : null;
  ctx.globalAlpha=alpha;
  ctx.globalCompositeOperation=operation||'source-over';
  if(rendered){
    ctx.drawImage(rendered.canvas,rendered.sx,rendered.sy,rendered.width,rendered.height,
                  0,0,w,h);
    return;
  }
  /* The shared 3D renderer is orthographic. Its X/Y plane projection is
     exactly cos(angle) on the affected axis, so this Canvas2D fallback keeps
     the same declared projection on browsers without WebGL. */
  const cosine=Math.max(0,Math.abs(Math.cos(degrees*Math.PI/180)));
  ctx.save(); ctx.translate(w/2,h/2);
  ctx.scale(axis==='y'?cosine:1,axis==='x'?cosine:1);
  ctx.drawImage(frame,-w/2,-h/2,w,h); ctx.restore();
}
const warnedUnsupportedTransitions=new Set();
function paintTransitionCanvas(ctx,mode,phase,w,h,drawIncoming){
  const spatial=transitionModePlan(mode,phase,w,h),t=spatial.t;
  const capability=transitionModeCapability(mode);
  /* Exact endpoints keep transparent Clips exact and avoid running spatial
     geometry for a zero-radius/zero-width frame. */
  if(t<=0) return;
  if(t>=1){
    ctx.save(); ctx.setTransform(1,0,0,1,0,0); ctx.filter='none';
    ctx.globalAlpha=1; ctx.globalCompositeOperation='source-over';
    ctx.clearRect(0,0,w,h); drawIncoming(ctx); ctx.restore();
    return;
  }
  if(!capability.supported){
    /* Imported state can still contain a native/creative mixer. Hold the old
       Clip, then let the caller make the normal cut at t=1; never disguise an
       unknown algorithm as Dissolve. The offline UI exposes the same reason. */
    if(!warnedUnsupportedTransitions.has(String(mode))){
      warnedUnsupportedTransitions.add(String(mode));
      console.warn('[openlive] '+String(mode)+': '+capability.reason);
    }
    return;
  }
  /* The engine resolves Random exactly once at trigger time. If an externally
     constructed runtime bypasses that contract, hold for a cut instead of
     re-rolling every frame or pretending Random means Alpha. */
  if(capability.kind==='random') return;
  if(capability.kind==='cut'){
    if(t<.5) return;
    ctx.save(); ctx.setTransform(1,0,0,1,0,0); ctx.filter='none';
    ctx.globalAlpha=1; ctx.globalCompositeOperation='source-over';
    ctx.clearRect(0,0,w,h); drawIncoming(ctx); ctx.restore();
    return;
  }
  if(capability.kind==='mixer'){
    const mixerPlan=EN.mixerPlan(mode,t);
    if(mixerPlan.operation!=='source-over'){
      paintMixerCanvas(ctx,mixerPlan,w,h,drawIncoming);
      return;
    }
    /* Preserve the existing transparent-safe crossfade for a regular mixer
       whose Canvas operation is normal/source-over. */
  }
  if(capability.kind==='through-color'){
    withTransitionFrames(ctx,w,h,drawIncoming,(outgoing,incoming)=>{
      ctx.fillStyle=spatial.color; ctx.fillRect(0,0,w,h);
      if(spatial.outgoingAlpha>0){
        ctx.globalAlpha=spatial.outgoingAlpha;
        ctx.globalCompositeOperation='source-over'; ctx.drawImage(outgoing,0,0,w,h);
      }
      if(spatial.incomingAlpha>0){
        ctx.globalAlpha=spatial.incomingAlpha;
        ctx.globalCompositeOperation='source-over'; ctx.drawImage(incoming,0,0,w,h);
      }
    });
    return;
  }
  if(capability.kind==='push'){
    withTransitionFrames(ctx,w,h,drawIncoming,(outgoing,incoming)=>{
      ctx.drawImage(outgoing,spatial.outgoing.x,spatial.outgoing.y,w,h);
      ctx.drawImage(incoming,spatial.incoming.x,spatial.incoming.y,w,h);
    });
    return;
  }
  if(capability.kind==='ellipse'){
    withRenderScratch(w,h,incoming=>{
      drawIncoming(incoming);
      const e=spatial.ellipse;
      ctx.save(); ctx.setTransform(1,0,0,1,0,0);
      ctx.beginPath(); ctx.ellipse(e.cx,e.cy,e.rx,e.ry,0,0,Math.PI*2); ctx.clip();
      /* Clearing inside the reveal matters when the incoming Clip has alpha:
         a completed wipe must not leave the old Clip behind transparent pixels. */
      ctx.clearRect(0,0,w,h); ctx.globalAlpha=1;
      ctx.globalCompositeOperation='source-over'; ctx.drawImage(incoming.canvas,0,0,w,h);
      ctx.restore();
    });
    return;
  }
  if(capability.kind==='zoom'){
    withTransitionFrames(ctx,w,h,drawIncoming,(outgoing,incoming)=>{
      drawScaledTransitionFrame(ctx,outgoing,spatial.outgoingScale,w,h,
        spatial.outgoingAlpha,'source-over');
      drawScaledTransitionFrame(ctx,incoming,spatial.incomingScale,w,h,
        spatial.incomingAlpha,'lighter');
    });
    return;
  }
  if(capability.kind==='rotate'){
    withTransitionFrames(ctx,w,h,drawIncoming,(outgoing,incoming)=>{
      drawRotatedTransitionFrame(ctx,outgoing,spatial.axis,spatial.outgoingAngle,w,h,
        spatial.outgoingAlpha,'source-over');
      drawRotatedTransitionFrame(ctx,incoming,spatial.axis,spatial.incomingAngle,w,h,
        spatial.incomingAlpha,'lighter');
    });
    return;
  }
  if(capability.kind==='side-by-side'){
    withTransitionFrames(ctx,w,h,drawIncoming,(outgoing,incoming)=>{
      const a=spatial.outgoing,b=spatial.incoming;
      if(a.width>0) ctx.drawImage(outgoing,a.x,a.y,a.width,a.height);
      if(b.width>0) ctx.drawImage(incoming,b.x,b.y,b.width,b.height);
    });
    return;
  }
  if(capability.kind==='tile'){
    withRenderScratch(w,h,incoming=>{
      drawIncoming(incoming);
      ctx.save(); ctx.setTransform(1,0,0,1,0,0); ctx.filter='none';
      ctx.globalAlpha=1; ctx.globalCompositeOperation='source-over';
      spatial.tiles.forEach(tile=>{
        if(!(tile.phase>0)) return;
        const dw=tile.width*tile.phase,dh=tile.height*tile.phase;
        const dx=tile.x+(tile.width-dw)/2,dy=tile.y+(tile.height-dh)/2;
        ctx.clearRect(dx,dy,dw,dh);
        ctx.drawImage(incoming.canvas,tile.x,tile.y,tile.width,tile.height,dx,dy,dw,dh);
      });
      ctx.restore();
    });
    return;
  }
  /* Alpha and Dissolve are explicit premultiplied crossfades of two complete
     Clip frames. Plain source-over would leave the outgoing Clip visible
     through transparent incoming pixels until a one-frame pop at the end. */
  withRenderScratch(w,h,incoming=>{
    drawIncoming(incoming);
    ctx.save();
    ctx.setTransform(1,0,0,1,0,0); ctx.filter='none';
    ctx.globalAlpha=1-t;
    ctx.globalCompositeOperation='destination-in';
    ctx.fillStyle='#fff'; ctx.fillRect(0,0,w,h);
    ctx.globalAlpha=t;
    ctx.globalCompositeOperation='lighter';
    ctx.drawImage(incoming.canvas,0,0,w,h);
    ctx.restore();
  });
}
/* A threshold measured from the end of the previous paint aliases badly with
   rAF. At 30 fps on a 60 Hz display, a 2-3 ms paint makes the next two rAF
   timestamps both look "too early", so the third callback wins and the result
   settles near 20-23 fps. This cadence owns an absolute phase instead: each
   completed opportunity advances the deadline by the configured interval,
   independent of paint cost. Rates such as 24 and 25 therefore alternate two
   and three display refreshes without accumulating drift. */
function createPhaseCadence(){
  const EPSILON_MS=0.5;
  let signature='', interval=0, nextAt=NaN, lastNow=NaN;
  function reset(){
    signature=''; interval=0; nextAt=NaN; lastNow=NaN;
  }
  function due(now, requestedInterval, mode){
    now=Number(now);
    if(!Number.isFinite(now)) return false;
    const gap=Math.max(0,Number(requestedInterval)||0);
    const nextSignature=String(mode||'')+'|'+String(gap);
    const clockRewound=Number.isFinite(lastNow) && now+EPSILON_MS<lastNow;
    lastNow=now;
    if(nextSignature!==signature || clockRewound || !Number.isFinite(nextAt)){
      signature=nextSignature; interval=gap; nextAt=now;
    }
    if(interval<=0){ nextAt=now; return true; }
    if(now+EPSILON_MS<nextAt) return false;
    /* Skip missed deadlines in one arithmetic step. A background pause produces
       one fresh frame, never a burst trying to repay every missed frame. */
    nextAt += (Math.floor((now+EPSILON_MS-nextAt)/interval)+1)*interval;
    return true;
  }
  return {due,reset};
}
const monitorPaintCadence=createPhaseCadence();
let compositionCadenceSignature='';
let fpsEMA = 0, fpsLastAt = 0;
function resetCompositionPaintCadence(){
  monitorPaintCadence.reset(); compositionCadenceSignature='';
  fpsEMA=0; fpsLastAt=0;
}
function compositionPaintGap(base){
  if(S.live) return base||0;
  const configured=EN.compositionFrameInterval ? EN.compositionFrameInterval() : 0;
  return Math.max(base||0,configured||0);
}
function responsivePaintGap(){
  /* Canvas CPU effects can consume 30–80 ms at full HD. Starting another
     full-frame task immediately after each completion starves pointer and key
     input even though the frame lane is technically single-flight. Preserve
     pixels, but reduce cadence in stable steps until each cycle leaves the
     main thread breathing room. Fast/GPU-only shows remain at their configured
     rate. */
  if(lastMonitorPaintCost>=50) return 100;       // 10 fps safety lane
  if(lastMonitorPaintCost>=30) return 1000/15;   // 15 fps
  if(lastMonitorPaintCost>=18) return 1000/30;   // 30 fps
  return 0;
}
function compositionPaintMode(driver){
  const demand=programmeOutputActive ? 'output'
    : previewOutputActive ? 'preview'
    : compositionSourceActive ? 'composition'
    : sourceDemandActive ? 'routed' : 'ui';
  return [driver,S.live?'live':'offline',demand].join(':');
}
function paintMonitorsScheduled(now,driver){
  driver=driver==='background'?'background':'visible';
  syncCompositionRenderSurface();
  const baseGap=driver==='background' ? (programmeOutputActive ? 15 : 30)
    : (programmeOutputActive ? 15 : 0);
  const minGap=Math.max(compositionPaintGap(baseGap),responsivePaintGap());
  const mode=compositionPaintMode(driver);
  const signature=mode+'|'+String(minGap);
  if(signature!==compositionCadenceSignature){
    compositionCadenceSignature=signature;
    monitorPaintCadence.reset(); fpsEMA=0; fpsLastAt=0;
  }
  if(!monitorPaintCadence.due(now,minGap,mode)) return false;
  const started = performance.now();
  drawMonitors(now);
  lastMonitorPaintCost = performance.now() - started;
  if(fpsLastAt){
    const dt=now-fpsLastAt;
    if(dt>0) fpsEMA=fpsEMA ? fpsEMA+((1000/dt)-fpsEMA)*0.1 : (1000/dt);
  }
  fpsLastAt=now;
  /* Programme resolution is invariant. Under load the single-flight frame
     lanes naturally drop cadence; they never discard source pixels. */
  programmeRenderScale = 1;
  return true;
}

/* ================= transport ================= */
const audioMixerRows=$('#audioMixerRows');
const audioMixerPopover=$('#audioMixerPopover');
const audioPreferencesLink=$('#audioPreferencesLink');
const audioMixerToggle=$('#audioMixerToggle');
const audioDesktopToggle=$('#audioDesktopToggle');
const audioCompactMic=$('#audioCompactMic');
const audioMixerTitlebar=$('#audioMixerTitlebar');
const audioAdvancedOverlay=$('#audioAdvancedOverlay');
const audioAdvancedRows=$('#audioAdvancedRows');
const AUDIO_MIXER_UI_KEY='openlive.audio-mixer.ui.v2';
const AUDIO_GLOBAL_KEY='openlive.audio-mixer.global.v1';
let audioMixerSignature='';
let audioAdvancedSignature='';
const audioGlobalCaptures=new Map();
const audioGlobalParams=new Map();
const audioCapturePending=new Set();

function readAudioMixerStored(key,fallback){
  try{
    const value=JSON.parse(localStorage.getItem(key)||'null');
    return value&&typeof value==='object'?value:fallback;
  }catch(error){ return fallback; }
}
const audioMixerStored=readAudioMixerStored(AUDIO_MIXER_UI_KEY,{});
const audioGlobalStored=readAudioMixerStored(AUDIO_GLOBAL_KEY,{});
let audioMixerScope=audioMixerStored.scope==='all'?'all':'active';
let audioMixerLayout=audioMixerStored.layout==='horizontal'?'horizontal':'vertical';
let audioMixerShowHidden=!!audioMixerStored.showHidden;
let audioMixerKeepHiddenLast=audioMixerStored.keepHiddenLast!==false;
let audioMixerKeepInactiveLast=audioMixerStored.keepInactiveLast!==false;
const audioChannelView=new Map(Object.entries(audioMixerStored.channels||{}));
let audioMixerDrag=null;
let audioAdvancedOpener=null;

function persistAudioMixerUi(){
  const channels={}; audioChannelView.forEach((value,key)=>channels[key]=value);
  const r=audioMixerPopover&&!audioMixerPopover.hidden?audioMixerPopover.getBoundingClientRect():null;
  const inline=audioMixerPopover&&audioMixerPopover.style.left?{
    left:Math.round(parseFloat(audioMixerPopover.style.left)||4),
    top:Math.round(parseFloat(audioMixerPopover.style.top)||24),
    width:Math.round(parseFloat(audioMixerPopover.style.width)||(audioMixerStored.geometry&&audioMixerStored.geometry.width)||720),
    height:Math.round(parseFloat(audioMixerPopover.style.height)||(audioMixerStored.geometry&&audioMixerStored.geometry.height)||420)
  }:audioMixerStored.geometry;
  const geometry=r&&r.width>0?{left:Math.round(r.left),top:Math.round(r.top),
    width:Math.round(r.width),height:Math.round(r.height)}:inline;
  try{ localStorage.setItem(AUDIO_MIXER_UI_KEY,JSON.stringify({
    open:!audioMixerPopover.hidden,scope:audioMixerScope,layout:audioMixerLayout,
    showHidden:audioMixerShowHidden,keepHiddenLast:audioMixerKeepHiddenLast,
    keepInactiveLast:audioMixerKeepInactiveLast,
    geometry,channels
  })); }catch(error){}
}
function audioChannelState(key){
  key=String(key); let state=audioChannelView.get(key);
  if(!state||typeof state!=='object'){
    state={hidden:false,pinned:false,locked:false}; audioChannelView.set(key,state);
  }
  return state;
}
function persistGlobalAudioState(){
  const saved={};
  audioGlobalParams.forEach((record,key)=>{
    saved[key]={volume:audioParameterValue(record.volume),pan:audioParameterValue(record.pan),
      muted:!!audioParameterValue(record.muted)};
  });
  try{ localStorage.setItem(AUDIO_GLOBAL_KEY,JSON.stringify(Object.assign({},audioGlobalStored,saved))); }
  catch(error){}
}
function globalAudioLabel(key){ return key==='global:mic'?'Microphone Input':'Desktop Audio'; }
function ensureGlobalAudioParams(key){
  key=String(key); const prior=audioGlobalParams.get(key);
  if(prior&&EN.parameterByHome(prior.volume.home)===prior.volume) return prior;
  /* A Composition replacement clears the engine registry. Seed replacement
     Parameters from the still-live controls before falling back to disk. */
  const saved=prior ? {volume:audioParameterValue(prior.volume),pan:audioParameterValue(prior.pan),
    muted:!!audioParameterValue(prior.muted)} : (audioGlobalStored[key]||{});
  const home='/openlive/audio-mixer/'+(key==='global:mic'?'mic':'desktop');
  const made=EN.makeParams(home,[
    {n:'Volume',path:'volume',kind:'range',min:0,max:1,d:Number.isFinite(+saved.volume)?+saved.volume:1},
    {n:'Pan',path:'pan',kind:'range',min:-1,max:1,d:Number.isFinite(+saved.pan)?+saved.pan:0},
    {n:'Mute',path:'mute',kind:'bool',d:!!saved.muted}
  ]);
  const record={volume:made[0],pan:made[1],muted:made[2]};
  Object.values(record).forEach(parameter=>parameter.globalKey=key);
  audioGlobalParams.set(key,record); return record;
}

function audioParameterFor(layer,field){
  field=field||'volume';
  if(typeof layer==='string'&&layer.startsWith('global:')){
    return ensureGlobalAudioParams(layer)[field]||null;
  }
  if(S.live){
    const owner=layer ? AL.layer(layer) : AL.comp;
    return owner&&owner.audio&&owner.audio[field];
  }
  const owner=layer ? EN.layer(layer) : EN.comp();
  return owner&&owner.audio&&owner.audio[field];
}
function audioParameterValue(parameter){
  const value=+(parameter&&parameter.globalKey?EN.val(parameter):(S.live?AL.val(parameter):EN.val(parameter)));
  return Number.isFinite(value)?value:0;
}
function audioParameterBounds(parameter){
  const min=Number.isFinite(+parameter.min)?+parameter.min:0;
  const max=Number.isFinite(+parameter.max)&&+parameter.max>min?+parameter.max:1;
  return {min,max};
}
function audioParameterNormalised(parameter){
  if(!parameter) return 0;
  const bounds=audioParameterBounds(parameter),value=audioParameterValue(parameter);
  return clamp((value-bounds.min)/(bounds.max-bounds.min),0,1);
}
function audioParameterDb(parameter){
  if(!parameter) return -60;
  const bounds=audioParameterBounds(parameter),value=audioParameterValue(parameter);
  return bounds.min<-2 ? Math.max(-60,value) : Math.max(-60,20*Math.log10(Math.max(value,.001)));
}
function audioDbText(db){ return db<=-59.9?'−∞':db.toFixed(1); }
function audioDbAriaText(db){ return db<=-59.9?'minus infinity decibels':db.toFixed(1)+' decibels'; }
function audioFaderNormalised(parameter){
  if(!parameter) return 0;
  return clamp((audioParameterDb(parameter)+60)/60,0,1);
}
function audioFaderValue(parameter,normalised){
  const bounds=audioParameterBounds(parameter),db=-60+clamp(normalised,0,1)*60;
  if(bounds.min<-2) return clamp(db,bounds.min,bounds.max);
  return db<=-59.9?bounds.min:clamp(Math.pow(10,db/20),bounds.min,bounds.max);
}
function writeAudioValue(parameter,value,opts){
  if(!parameter) return;
  if(parameter.globalKey){
    EN.setParam(parameter,value,opts); persistGlobalAudioState();
    syncGlobalAudioChannel(parameter.globalKey);
    return;
  }
  if(S.live) AL.setParam(parameter.id,value);
  else EN.setParam(parameter,value,opts);
}
function writeAudioParameter(parameter,normalised,opts){
  if(!parameter) return;
  const bounds=audioParameterBounds(parameter);
  writeAudioValue(parameter,bounds.min+clamp(normalised,0,1)*(bounds.max-bounds.min),opts);
}
function writeAudioFader(parameter,normalised,opts){
  if(parameter) writeAudioValue(parameter,audioFaderValue(parameter,normalised),opts);
}
function resetAudioParameter(parameter,opts){
  if(!parameter) return;
  if(parameter.globalKey){ EN.reset(parameter,opts); persistGlobalAudioState(); syncGlobalAudioChannel(parameter.globalKey); }
  else if(S.live) AL.resetParam(parameter.id); else EN.reset(parameter,opts);
}
function toggleAudioMute(model){
  const parameter=audioParameterFor(model.layer,'muted');
  if(!parameter) return msg('Mute is unavailable for this connected Audio source.');
  writeAudioValue(parameter,!audioParameterValue(parameter));
}
function currentCompositionAudioSpec(){
  if(S.live) return {volume:1,pan:0,muted:false,effects:[]};
  const comp=EN.comp(); if(!comp||!comp.audio) return {volume:1,pan:0,muted:false,effects:[]};
  return {effects:audioFxState(comp.audio.effects),
    volume:EV(comp.audio.volume)*EV(comp.master)*(EV(comp.bypassed)?0:1),
    pan:EV(comp.audio.pan),muted:!!EV(comp.audio.muted)};
}
function syncGlobalAudioChannel(key,compositionSpec){
  const stream=audioGlobalCaptures.get(key);
  if(!stream||!MEDIA) return false;
  const tracks=stream.getAudioTracks?stream.getAudioTracks():[];
  if(!tracks.some(track=>track.readyState!=='ended')) return false;
  /* A microphone is an input meter/FFT source, never a programme source. Its
     dedicated ArenaMedia graph has no path to the Composition bus, output
     destination, recording tap or streaming tap. Desktop Audio remains a
     normal mixed source. */
  if(key==='global:mic') return !!(MEDIA.attachInputMeter&&
    MEDIA.attachInputMeter(key,stream,globalAudioLabel(key)));
  if(!MEDIA.attachLive||!MEDIA.syncLive) return false;
  const params=ensureGlobalAudioParams(key);
  MEDIA.attachLive(key,stream,globalAudioLabel(key));
  MEDIA.syncLive(key,{volume:audioParameterValue(params.volume),pan:audioParameterValue(params.pan),
    muted:!!audioParameterValue(params.muted),audioEnabled:true,effects:[],
    composition:compositionSpec||currentCompositionAudioSpec()});
  return true;
}
function syncGlobalAudioChannels(compositionSpec){
  audioGlobalCaptures.forEach((stream,key)=>syncGlobalAudioChannel(key,compositionSpec));
}
function emptyAudioLevels(channelCount){
  return {left:0,right:0,peak:0,db:-60,channelCount:channelCount||2,
    ppm:{left:0,right:0,leftDb:-60,rightDb:-60,db:-60},
    vu:{left:0,right:0,leftDb:-60,rightDb:-60,db:-60},
    peakHold:{left:0,right:0,leftDb:-60,rightDb:-60,db:-60},
    inputPeak:{left:0,right:0,leftDb:-60,rightDb:-60,db:-60,leftZone:'silent',rightZone:'silent',active:false},
    clipping:{left:false,right:false,any:false}};
}
function audioMixerRowModel(snapshot,forceAll){
  const empty=emptyAudioLevels(snapshot.channelCount);
  const rows=[{key:'composition',layer:0,name:'Show',source:'Master Output',
    levels:snapshot.master||empty,master:true,global:true,active:true,status:'Global'}];
  (snapshot.sources||[]).filter(source=>source.layer==null).forEach(source=>rows.push({
    key:source.key,layer:source.key,name:source.name||globalAudioLabel(source.key),
    source:'Global Audio Input',levels:source.levels||empty,global:true,
    active:source.active!==false,status:'Global'}));
  const layerSources=new Map((snapshot.sources||[]).filter(source=>source.layer!=null)
    .map(source=>[+source.layer,source]));
  if(S.live){
    layerSources.forEach((source,index)=>{
      if(!forceAll&&audioMixerScope==='active'&&source.active===false) return;
      rows.push({key:'layer:'+index,layer:index,name:'Layer '+index,source:source.name||'Audio Clip',
        levels:source.levels||empty,active:source.active!==false,status:source.active===false?'Inactive':'Active'});
    });
  }else{
    EN.layers().forEach(layer=>{
      const source=layerSources.get(layer.index),active=!!(source&&source.active!==false);
      if(!forceAll&&audioMixerScope==='active'&&!active) return;
      rows.push({key:'layer:'+layer.index,layer:layer.index,name:EN.displayName(layer)||('Layer '+layer.index),
        source:source&&source.name||'No active audio Clip',levels:source&&source.levels||empty,
        active,status:active?'Active':'Inactive'});
    });
  }
  rows.forEach(model=>{
    model.ui=audioChannelState(model.key);
    if(model.ui.hidden) model.status='Hidden';
    model.displayName=model.source&&model.source!=='Master Output'
      ? model.name+' · '+model.source : model.name;
  });
  const order=model=>model.master?0:model.global?1:model.ui.pinned?2:
    audioMixerKeepHiddenLast&&model.ui.hidden?5:
      audioMixerKeepInactiveLast&&!model.active?4:3;
  rows.sort((a,b)=>{
    if(audioMixerKeepHiddenLast||audioMixerKeepInactiveLast){ const d=order(a)-order(b); if(d) return d; }
    return String(a.displayName).localeCompare(String(b.displayName),undefined,{sensitivity:'base'});
  });
  return rows.filter(model=>model.master||forceAll||!model.ui.hidden||audioMixerShowHidden);
}
function openAudioEffectsFor(model){
  if(model.master){ switchPane('pComp'); render.panel(); return; }
  if(model.global) return msg(model.name+' uses the Show Audio effects chain.');
  if(model.layer){ S.selLayer=model.layer; switchPane('pLayer'); render.panel(); }
  else switchPane('pComp');
}
function renameAudioChannel(model){
  if(model.global||model.master) return msg('Global Audio channel names follow their source.');
  const owner=S.live?AL.layer(model.layer):EN.layer(model.layer),parameter=owner&&owner.name;
  if(!parameter) return msg('This Audio channel cannot be renamed.');
  const before=String(S.live?AL.val(parameter):EN.val(parameter)||model.name);
  const next=prompt('Rename Audio channel',before); if(next==null||!next.trim()) return;
  if(S.live) AL.setParam(parameter.id,next.trim()); else EN.setParam(parameter,next.trim());
  audioMixerSignature=''; render.all();
}
function resetAudioChannel(model){
  const params=['volume','pan','muted'].map(field=>audioParameterFor(model.layer,field)).filter(Boolean);
  if(S.live){ params.forEach(parameter=>resetAudioParameter(parameter)); }
  else EN.transaction('Reset Audio Mixer · '+model.name,()=>params.forEach(parameter=>EN.reset(parameter,{noUndo:true})));
  if(model.global){ persistGlobalAudioState(); syncGlobalAudioChannel(model.key); }
  updateAudioMixer(performance.now());
}
function unhideAllAudioChannels(){
  audioChannelView.forEach(state=>state.hidden=false); audioMixerShowHidden=false;
  audioMixerSignature=''; persistAudioMixerUi(); updateAudioMixer(performance.now());
}
function audioChannelMenuItems(model){
  const fixed=!!(model.master||model.global),ui=audioChannelState(model.key);
  return [
    {l:'Unhide All',dis:![...audioChannelView.values()].some(state=>state.hidden),fn:unhideAllAudioChannels},
    {sep:1},
    {l:ui.pinned?'Unpin':'Pin',dis:fixed,title:fixed?'Global channels remain at the start of the mixer.':'',
      fn:()=>{ ui.pinned=!ui.pinned; persistAudioMixerUi(); audioMixerSignature=''; updateAudioMixer(performance.now()); }},
    {l:ui.hidden?'Unhide':'Hide',dis:fixed||ui.pinned,
      title:fixed?'Global channels remain visible.':ui.pinned?'Unpin this source before hiding it.':'',
      fn:()=>{ ui.hidden=!ui.hidden; persistAudioMixerUi(); audioMixerSignature=''; updateAudioMixer(performance.now()); }},
    {l:'Lock Volume',check:1,tick:!!ui.locked,fn:()=>{
      ui.locked=!ui.locked; persistAudioMixerUi(); audioMixerSignature=''; updateAudioMixer(performance.now()); }},
    {sep:1},
    {l:'Copy Audio Effects',dis:1,title:'Audio Effect clipboard support is not available in this mixer yet.'},
    {l:'Paste Audio Effects',dis:1,title:'Copy Audio Effects from a compatible inspector first.'},
    {sep:1},
    {l:'Rename…',dis:fixed,title:fixed?'This name follows the global source.':'',fn:()=>renameAudioChannel(model)},
    {sep:1},
    {l:'Audio Effects',fn:()=>openAudioEffectsFor(model)},
    {l:'Reset Volume and Balance',fn:()=>resetAudioChannel(model)},
    {l:'Properties',fn:()=>openAdvancedAudioProperties(model.key)},
    ...(model.global&&!model.master?[{sep:1},{l:'Remove',fn:()=>removeGlobalAudioCapture(model.key)}]:[])
  ];
}
function openAudioChannelMenu(event,button,model){
  if(event){ event.preventDefault(); event.stopPropagation(); }
  const rect=button.getBoundingClientRect();
  buildDD(audioChannelMenuItems(model),Math.min(rect.left,innerWidth-250),rect.bottom+2,0,null,button);
}
function beginAudioParameterGesture(input,parameter,label,writer){
  let gesture=null;
  input.addEventListener('pointerdown',event=>{
    if(event.button!==0||input.disabled) return;
    input.dataset.dragging='1';
    gesture=S.live&&!parameter.globalKey?null:EN.beginParamGesture(parameter,label);
    try{ input.setPointerCapture(event.pointerId); }catch(error){}
  });
  input.addEventListener('input',()=>writer(input,gesture?{noUndo:true}:undefined));
  const finish=()=>{
    delete input.dataset.dragging;
    if(gesture){ EN.endParamGesture(gesture); gesture=null; }
  };
  input.addEventListener('pointerup',finish); input.addEventListener('pointercancel',finish);
  input.addEventListener('lostpointercapture',finish);
}
function bindAudioParameterContext(control,getParameter,label){
  const open=(event,keyboard)=>{
    const parameter=getParameter(); if(!parameter) return;
    event.preventDefault(); event.stopPropagation();
    const reset=()=>{ resetAudioParameter(parameter); updateAudioMixer(performance.now()); };
    const local=parameter.globalKey||!S.live?parameter:null;
    const rect=control.getBoundingClientRect();
    const menu=buildDD(parameterContextItems(local,reset,local?null:parameter.id),
      keyboard?rect.left:event.clientX,keyboard?rect.bottom:event.clientY,0,null,control);
    menu.setAttribute('aria-label',label+' Parameter shortcuts');
    if(keyboard) keyboardPresetMenu(menu,control,false);
  };
  control.addEventListener('contextmenu',event=>open(event,false));
  control.addEventListener('keydown',event=>{
    if(event.key!=='ContextMenu'&&!(event.shiftKey&&event.key==='F10')) return;
    open(event,true);
  });
}
function bindAudioMixerRow(row,model){
  const volume=audioParameterFor(model.layer),mute=audioParameterFor(model.layer,'muted');
  const slider=row.querySelector('.audio-volume'),sourceButton=row.querySelector('.audio-source-menu');
  sourceButton.addEventListener('click',event=>openAudioChannelMenu(event,sourceButton,model));
  row.addEventListener('contextmenu',event=>openAudioChannelMenu(event,sourceButton,model));
  beginAudioParameterGesture(slider,volume,'Audio Mixer · '+model.name,(input,opts)=>{
    if(audioChannelState(model.key).locked) return;
    row.querySelector('.audio-fader-shell').style.setProperty('--audio-fader',String(+input.value/1000));
    writeAudioFader(audioParameterFor(model.layer),+input.value/1000,opts);
  });
  bindAudioParameterContext(slider,()=>audioParameterFor(model.layer),model.name+' Volume');
  slider.addEventListener('dblclick',event=>{
    event.preventDefault(); const current=audioParameterFor(model.layer); if(!current) return;
    const entered=prompt('Set '+model.name+' volume in dB',audioParameterDb(current).toFixed(1));
    if(entered==null||!Number.isFinite(+entered)) return;
    writeAudioFader(current,clamp((+entered+60)/60,0,1));
  });
  const muteButton=row.querySelector('.audio-mute');
  muteButton.addEventListener('click',()=>toggleAudioMute(model));
  bindAudioParameterContext(muteButton,()=>audioParameterFor(model.layer,'muted'),model.name+' Mute');
  row.querySelector('.audio-monitor').disabled=true;
  if(!volume) slider.disabled=true;
  if(!mute) row.querySelector('.audio-mute').disabled=true;
}
function audioMeterMarkup(name){
  const lane=side=>'<span class="audio-meter-lane '+side+'"><i class="audio-meter-fill"></i><i class="audio-meter-vu"></i><i class="audio-meter-peak-line"></i><i class="audio-meter-input"></i></span>';
  return '<div class="audio-strip-meter" role="meter" aria-label="'+esc(name)+' audio level" aria-valuemin="-60" aria-valuemax="0" aria-valuenow="-60">'+
    lane('left')+lane('right')+'<span class="audio-meter-scale" aria-hidden="true"><span>0</span><span>-6</span><span>-12</span><span>-18</span><span>-24</span><span>-30</span><span>-36</span><span>-42</span><span>-48</span><span>-54</span><span>-60</span></span></div>';
}
function rebuildAudioMixerRows(models){
  audioMixerRows.textContent='';
  models.forEach(model=>{
    const row=document.createElement('section');
    row.className='audio-mixer-row'+(model.master?' master':'')+(model.global?' global-channel':'')+
      (!model.active?' inactive':'')+(model.ui.hidden?' hidden-channel':'')+(model.ui.locked?' locked':'');
    row.dataset.audioKey=model.key; row.setAttribute('aria-label',model.displayName+' Audio channel');
    row.innerHTML='<span class="audio-status">'+esc(model.status)+'</span>'+
      '<button class="audio-source-menu" type="button" aria-haspopup="menu" aria-expanded="false" title="'+esc(model.displayName)+'"><span class="audio-source-name audio-source">'+esc(model.displayName)+'</span><span class="audio-source-chevron" aria-hidden="true">&#9662;</span></button>'+
      '<span class="audio-db">−∞ dB</span>'+
      '<div class="audio-fader-shell"><i class="audio-fader-rail" aria-hidden="true"></i><i class="audio-fader-fill" aria-hidden="true"></i><i class="audio-fader-handle" aria-hidden="true"></i>'+
      '<input class="audio-volume" type="range" min="0" max="1000" value="0" aria-label="'+esc(model.displayName)+' volume" aria-valuemin="-60" aria-valuemax="0" aria-valuetext="minus infinity decibels"></div>'+
      audioMeterMarkup(model.displayName)+
      '<div class="audio-channel-controls"><button type="button" class="audio-channel-button audio-mute" aria-label="Mute '+esc(model.displayName)+'" aria-pressed="false" title="Mute '+esc(model.displayName)+'"><svg class="audio-speaker-icon" aria-hidden="true" viewBox="0 0 16 16"><path d="M2 6h3l3-3v10l-3-3H2z"/><path d="M10 5c1.5 1.5 1.5 4.5 0 6M12 3c3 3 3 7 0 10" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round"/></svg><span class="audio-control-label" aria-hidden="true">MUTE</span></button>'+
      '<button type="button" class="audio-channel-button audio-monitor" data-audio-control="headphone-monitor" aria-label="Headphone monitor unavailable for '+esc(model.displayName)+'" aria-pressed="false" aria-disabled="true" title="HEADPHONE MONITOR: not a microphone. + MIC METER shows input levels only and never routes them to output."><svg class="audio-headphone-icon" aria-hidden="true" viewBox="0 0 16 16"><path d="M3 9V7a5 5 0 0 1 10 0v2" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M2 8h3v5H3a1 1 0 0 1-1-1zm9 0h3v4a1 1 0 0 1-1 1h-2z"/></svg><span class="audio-control-label" aria-hidden="true">MON</span></button></div>';
    audioMixerRows.appendChild(row); bindAudioMixerRow(row,model);
  });
}
function meterValue(levels,group,side,fallback){
  const value=levels&&levels[group]&&+levels[group][side];
  return Number.isFinite(value)?clamp(value,0,1):clamp(+(levels&&levels[fallback||side])||0,0,1);
}
function applyAudioControlMappings(control,parameter){
  if(!control) return;
  const local=parameter&&(parameter.globalKey||!S.live),kinds=local&&EN.controlMappingKinds
    ? EN.controlMappingKinds(parameter) : [];
  const animated=!!(local&&parameter.anim),linked=!!(local&&parameter.dash);
  const signature=kinds.join(',')+'|'+Number(animated)+'|'+Number(linked);
  if(control.dataset.mappingKinds===signature) return;
  control.dataset.mappingKinds=signature;
  ['keyboard','midi','osc','dmx'].forEach(kind=>control.classList.toggle('mapped-'+kind,kinds.includes(kind)));
  control.classList.toggle('animated',animated); control.classList.toggle('linked',linked);
  if(!control.dataset.mappingBaseTitle) control.dataset.mappingBaseTitle=control.title||'';
  control.title=control.dataset.mappingBaseTitle+(kinds.length?'; mapped: '+kinds.join(', '):'')+
    (animated?': animated':'')+(linked?': Quick Controls linked':'');
}
function paintAudioMeter(element,levels){
  if(!element||!levels) return;
  const horizontal=element.classList.contains('audio-compact-meter')||
    element.classList.contains('audio-master-meter')||audioMixerLayout==='horizontal';
  ['left','right'].forEach(side=>{
    const lane=element.querySelector('.audio-meter-lane.'+side); if(!lane) return;
    const ppm=meterValue(levels,'ppm',side,side),vu=meterValue(levels,'vu',side,side);
    const peak=meterValue(levels,'peakHold',side,'peak'),input=meterValue(levels,'inputPeak',side,'peak');
    const fill=lane.querySelector('.audio-meter-fill'),vuLine=lane.querySelector('.audio-meter-vu');
    const peakLine=lane.querySelector('.audio-meter-peak-line'),inputLine=lane.querySelector('.audio-meter-input');
    if(horizontal){
      fill.style.width=(ppm*100).toFixed(1)+'%'; fill.style.height='';
      vuLine.style.left=(vu*100).toFixed(1)+'%'; vuLine.style.bottom='';
      peakLine.style.left=(peak*100).toFixed(1)+'%'; peakLine.style.bottom='';
      inputLine.style.left=(input*100).toFixed(1)+'%'; inputLine.style.bottom='';
    }else{
      fill.style.height=(ppm*100).toFixed(1)+'%'; fill.style.width='';
      vuLine.style.bottom=(vu*100).toFixed(1)+'%'; vuLine.style.left='';
      peakLine.style.bottom=(peak*100).toFixed(1)+'%'; peakLine.style.left='';
      inputLine.style.bottom=(input*100).toFixed(1)+'%'; inputLine.style.left='';
    }
    const zone=levels.inputPeak&&levels.inputPeak[side+'Zone']||'silent'; inputLine.dataset.zone=zone;
    inputLine.hidden=input<=0;
  });
  element.classList.toggle('clipping',!!(levels.clipping&&levels.clipping.any));
  const db=Math.max(-60,Number.isFinite(+levels.db)?+levels.db:-60);
  element.setAttribute('aria-valuenow',db.toFixed(1));
  element.setAttribute('aria-valuetext',audioDbAriaText(db));
}
