  audioMixerPopover.classList.toggle('layout-horizontal',audioMixerLayout==='horizontal');
  const next=audioMixerLayout==='vertical'?'horizontal':'vertical',button=$('#audioMixerLayout');
  button.title='Use '+next+' layout';
