function removeGlobalAudioCapture(key,ended){
  const stream=audioGlobalCaptures.get(key); if(!stream) return false;
  audioGlobalCaptures.delete(key);
  if(!ended&&stream.getTracks) stream.getTracks().forEach(track=>{ try{ track.stop(); }catch(error){} });
  if(key==='global:mic'){
    if(MEDIA&&MEDIA.detachInputMeter) MEDIA.detachInputMeter(key);
  }else if(MEDIA&&MEDIA.detach) MEDIA.detach(key);
  audioMixerSignature=''; updateAudioMixer(performance.now());
  if(!ended) msg(key==='global:mic'?'Microphone input meter stopped.':globalAudioLabel(key)+' removed from Audio Mixer.');
  return true;
}

